base.src/core.js:
// The core holds at most CORE_POSTS terrain posts in all. Past it an allocation traps, the core
// restarts, and every loaded terrain is dropped. loadedPosts(core) is how many it holds now.
export const CORE_POSTS = 48e6;

export function loadedPosts(core) {
  return core.terrains.reduce((sum, t) => sum + t.posts, 0);
}

head.src/terrain-load.js:
import { CORE_POSTS } from './core.js';

// The step that fits a DEM in the core.
export function loadStep(dem) {
  let step = 1;
  while (Math.ceil(dem.width / step) * Math.ceil(dem.height / step) > CORE_POSTS) step += 1;
  return step;
}

export function loadTerrain(core, dem) {
  return core.addTerrain(dem, loadStep(dem));
}
